(function(){
  const previousRender=render;
  render=function(){const result=previousRender();if(page!=='settings')return result;const panel=$('.backupProtection .panelbody');if(panel&&!panel.querySelector('.backupGuidance')){const guide=document.createElement('div');guide.className='backupGuidance';guide.innerHTML='<h3>Backup &amp; Restore Guidelines</h3><ol><li><strong>Backup:</strong> Download the complete backup before clearing data or making major changes. Keep a copy on the Office PC and another approved storage location.</li><li><strong>Restore Backup:</strong> Use a complete workspace JSON file to recover the whole workspace. Review the file before confirming the restore.</li><li><strong>Restore Individual Entries:</strong> Use a complete workspace backup, select one module, then select the records to add. Existing IDs are not overwritten.</li><li><strong>Dependencies:</strong> Related records must exist before restoring dependent records. A Job Card may require its Customer, Vehicle, Service and Spare Part records.</li><li><strong>Safety:</strong> Restore operations do not replace settings, users, permissions or lists. Keep the latest complete backup before restoring.</li></ol>';panel.appendChild(guide)}return result};
  render();
})();
